-- [1/215] specialty:tim-mach - Chuyên khoa Tim mạch
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'tim-mach',
    'Chuyên khoa Tim mạch',
    'Chuyên khoa Tim mạch - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Tăng huyết áp, bệnh mạch vành, suy tim, rối loạn nhịp tim, hẹp hở van tim, xơ vữa động mạch. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Đau thắt ngực, khó thở khi gắng sức hoặc nằm đầu thấp, hồi hộp đánh trống ngực, phù hai chân, ngất xỉu. 3. Hướng dẫn chuẩn bị trước khi khám: Nhịn ăn 6-8 giờ làm xét nghiệm mỡ máu, mang theo đơn thuốc và nhật ký huyết áp đo tại nhà, nghỉ 15 phút trước đo. 4. Quy trình thăm khám và chăm sóc: Tiếp nhận đo sinh hiệu -> Khám lâm sàng tim phổi -> Đo ECG 12 chuyển đạo, siêu âm tim Doppler màu, xét nghiệm lipid máu -> Bác sĩ kết luận phác đồ và tư vấn chế độ ăn DASH. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Điều trị nội khoa tối ưu, thuốc hạ áp, NOAC, Holter ECG 24h, siêu âm Doppler tim, can thiệp stent mạch vành qua da.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Nhịn ăn 6-8 giờ làm xét nghiệm mỡ máu, mang theo đơn thuốc và nhật ký huyết áp đo tại nhà, nghỉ 15 phút trước đo", "primary_symptoms": "Đau thắt ngực, khó thở khi gắng sức hoặc nằm đầu thấp, hồi hộp đánh trống ngực, phù hai chân, ngất xỉu", "slug": "tim-mach", "treatment_modalities": "Điều trị nội khoa tối ưu, thuốc hạ áp, NOAC, Holter ECG 24h, siêu âm Doppler tim, can thiệp stent mạch vành qua da", "vietnamese_name": "Tim mạch"}'::jsonb,
