-- [3/215] specialty:tieu-hoa - Chuyên khoa Tiêu hóa - Gan mật
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'tieu-hoa',
    'Chuyên khoa Tiêu hóa - Gan mật',
    'Chuyên khoa Tiêu hóa - Gan mật - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Viêm loét dạ dày tá tràng nhiễm HP, trào ngược GERD, hội chứng ruột kích thích IBS, viêm đại tràng, viêm gan B/C, gan nhiễm mỡ, sỏi túi mật. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Đau thượng vị nóng rát, ợ hơi ợ chua, chướng bụng đầy hơi, đi ngoài phân đen hoặc máu, vàng da vàng mắt. 3. Hướng dẫn chuẩn bị trước khi khám: Nhịn ăn uống 6 giờ trước nội soi dạ dày, ngưng kháng sinh 4 tuần và PPI 2 tuần trước test thở C13, uống thuốc sạch ruột trước soi đại tràng. 4. Quy trình thăm khám và chăm sóc: Khám bụng lâm sàng -> Test hơi thở C13 hoặc nội soi tiêu hóa không đau NBI, siêu âm bụng tổng quát, FibroScan gan -> Phác đồ điều trị. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Phác đồ 4 thuốc Bismuth tiệt trừ HP 14 ngày, cắt polyp nội soi không đau, thuốc kháng virus viêm gan B/C, chế độ ăn Low-FODMAP.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Nhịn ăn uống 6 giờ trước nội soi dạ dày, ngưng kháng sinh 4 tuần và PPI 2 tuần trước test thở C13, uống thuốc sạch ruột trước soi đại tràng", "primary_symptoms": "Đau thượng vị nóng rát, ợ hơi ợ chua, chướng bụng đầy hơi, đi ngoài phân đen hoặc máu, vàng da vàng mắt", "slug": "tieu-hoa", "treatment_modalities": "Phác đồ 4 thuốc Bismuth tiệt trừ HP 14 ngày, cắt polyp nội soi không đau, thuốc kháng virus viêm gan B/C, chế độ ăn Low-FODMAP", "vietnamese_name": "Tiêu hóa"}'::jsonb,
