-- [5/215] specialty:nhi-khoa - Chuyên khoa Nhi
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'nhi-khoa',
    'Chuyên khoa Nhi',
    'Chuyên khoa Nhi - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Viêm phế quản, viêm phổi trẻ em, sốt phát ban, tiêu chảy cấp do rotavirus, tay chân miệng, biếng ăn, suy dinh dưỡng, còi xương. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Sốt cao, ho khò khè, thở nhanh rút lõm ngực, nôn trớ liên tục, bỏ bú, quấy khóc nhiều, phát ban đỏ ngoài da. 3. Hướng dẫn chuẩn bị trước khi khám: Mang theo sổ tiêm chủng và sổ theo dõi tăng trưởng, ghi lại giờ sốt và liều thuốc hạ sốt paracetamol đã dùng. 4. Quy trình thăm khám và chăm sóc: Tiếp nhận thân thiện -> Khám tai mũi họng, nghe tim phổi, đếm nhịp thở, đo SpO2 -> Xét nghiệm máu/vi sinh nhanh khi cần -> Kê đơn an toàn theo cân nặng. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Điều trị hạ sốt và bù nước điện giải Oresol, khí dung phế quản, tư vấn dinh dưỡng phục hồi và hướng dẫn phụ huynh theo dõi dấu hiệu nguy hiểm.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Mang theo sổ tiêm chủng và sổ theo dõi tăng trưởng, ghi lại giờ sốt và liều thuốc hạ sốt paracetamol đã dùng", "primary_symptoms": "Sốt cao, ho khò khè, thở nhanh rút lõm ngực, nôn trớ liên tục, bỏ bú, quấy khóc nhiều, phát ban đỏ ngoài da", "slug": "nhi-khoa", "treatment_modalities": "Điều trị hạ sốt và bù nước điện giải Oresol, khí dung phế quản, tư vấn dinh dưỡng phục hồi và hướng dẫn phụ huynh theo dõi dấu hiệu nguy hiểm", "vietnamese_name": "Nhi khoa"}'::jsonb,
