-- [7/215] specialty:co-xuong-khop - Chuyên khoa Cơ xương khớp
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'co-xuong-khop',
    'Chuyên khoa Cơ xương khớp',
    'Chuyên khoa Cơ xương khớp - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Thoái hóa khớp gối, thoái hóa cột sống thắt lưng, thoát vị đĩa đệm, viêm khớp dạng thấp, bệnh Gout cấp và mạn tính, loãng xương. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Đau nhức các khớp khi vận động, cứng khớp buổi sáng trên 30 phút, sưng nóng đỏ khớp ngón chân cái, tê bì dọc chân. 3. Hướng dẫn chuẩn bị trước khi khám: Mặc quần áo rộng rãi dễ bộc lộ khớp, mang theo phim chụp X-quang hoặc MRI cũ, thông báo thuốc giảm đau dạ dày đang dùng. 4. Quy trình thăm khám và chăm sóc: Khám tầm vận động khớp -> Chụp X-quang số hóa, đo mật độ xương DEXA, xét nghiệm acid uric máu và RF -> Phác đồ nội khoa kết hợp vật lý trị liệu. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Thuốc chống viêm NSAID, thuốc chống thoái hóa SYSADOA, tiêm huyết tương giàu tiểu cầu PRP nội khớp, chọc hút dịch khớp giải áp.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Mặc quần áo rộng rãi dễ bộc lộ khớp, mang theo phim chụp X-quang hoặc MRI cũ, thông báo thuốc giảm đau dạ dày đang dùng", "primary_symptoms": "Đau nhức các khớp khi vận động, cứng khớp buổi sáng trên 30 phút, sưng nóng đỏ khớp ngón chân cái, tê bì dọc chân", "slug": "co-xuong-khop", "treatment_modalities": "Thuốc chống viêm NSAID, thuốc chống thoái hóa SYSADOA, tiêm huyết tương giàu tiểu cầu PRP nội khớp, chọc hút dịch khớp giải áp", "vietnamese_name": "Cơ xương khớp"}'::jsonb,
