-- [9/215] specialty:da-lieu - Chuyên khoa Da liễu
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'da-lieu',
    'Chuyên khoa Da liễu',
    'Chuyên khoa Da liễu - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Viêm da cơ địa eczema, mụn trứng cá, vảy nến, mày đay, nấm da hắc lào lang ben, zona thần kinh, rụng tóc, chốc lở, ghẻ. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Ngứa da dữ dội, nổi mẩn đỏ sẩn phù, mụn nước, mụn mủ bọc, bong tróc vảy trắng bạc da đầu, tổn thương da trợt loét. 3. Hướng dẫn chuẩn bị trước khi khám: Không bôi thuốc mỡ hoặc mỹ phẩm lên vùng da tổn thương trong 24 giờ trước khi khám để bác sĩ quan sát rõ sang thương. 4. Quy trình thăm khám và chăm sóc: Khám sang thương da bằng đèn Wood/soi da Dermoscopy -> Soi tươi tìm nấm, ký sinh trùng Demodex -> Phác đồ thuốc bôi kết hợp thuốc uống. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Thuốc bôi corticoid kiểm soát liều, ức chế calcineurin, quang trị liệu UVB dải hẹp, dưỡng ẩm phục hồi hàng rào bảo vệ da.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Không bôi thuốc mỡ hoặc mỹ phẩm lên vùng da tổn thương trong 24 giờ trước khi khám để bác sĩ quan sát rõ sang thương", "primary_symptoms": "Ngứa da dữ dội, nổi mẩn đỏ sẩn phù, mụn nước, mụn mủ bọc, bong tróc vảy trắng bạc da đầu, tổn thương da trợt loét", "slug": "da-lieu", "treatment_modalities": "Thuốc bôi corticoid kiểm soát liều, ức chế calcineurin, quang trị liệu UVB dải hẹp, dưỡng ẩm phục hồi hàng rào bảo vệ da", "vietnamese_name": "Da liễu"}'::jsonb,
