-- [10/215] specialty:mat - Chuyên khoa Mắt (Nhãn khoa)
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'mat',
    'Chuyên khoa Mắt (Nhãn khoa)',
    'Chuyên khoa Mắt (Nhãn khoa) - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Tật khúc xạ cận viễn loạn thị, đục thủy tinh thể cườm khô, Glaucoma cườm nước, viêm kết mạc đau mắt đỏ, khô mắt, thoái hóa hoàng điểm. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Nhìn mờ, giảm thị lực, mỏi mắt, chảy nước mắt, đỏ mắt cộm rát như có cát, thấy chớp sáng đốm đen ruồi bay, nhìn đôi. 3. Hướng dẫn chuẩn bị trước khi khám: Tháo kính áp tròng 24 giờ trước đo khúc xạ, mang kính mắt đang đeo, không tự ý nhỏ thuốc nhỏ mắt chứa corticoid. 4. Quy trình thăm khám và chăm sóc: Đo thị lực và khúc xạ máy tự động -> Đo nhãn áp không tiếp xúc -> Khám sinh hiển vi bán phần trước và đáy mắt -> Kê đơn hoặc chỉ định phẫu thuật. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Cắt kính thuốc chuẩn xác, phẫu thuật Phaco tán nhuyễn thể thủy tinh đục, phẫu thuật Laser điều trị Glaucoma và tật khúc xạ.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Tháo kính áp tròng 24 giờ trước đo khúc xạ, mang kính mắt đang đeo, không tự ý nhỏ thuốc nhỏ mắt chứa corticoid", "primary_symptoms": "Nhìn mờ, giảm thị lực, mỏi mắt, chảy nước mắt, đỏ mắt cộm rát như có cát, thấy chớp sáng đốm đen ruồi bay, nhìn đôi", "slug": "mat", "treatment_modalities": "Cắt kính thuốc chuẩn xác, phẫu thuật Phaco tán nhuyễn thể thủy tinh đục, phẫu thuật Laser điều trị Glaucoma và tật khúc xạ", "vietnamese_name": "Mắt"}'::jsonb,
