-- [11/215] specialty:rang-ham-mat - Chuyên khoa Răng Hàm Mặt
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'rang-ham-mat',
    'Chuyên khoa Răng Hàm Mặt',
    'Chuyên khoa Răng Hàm Mặt - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Sâu răng, viêm tủy răng, viêm nướu tụt lợi, răng khôn mọc lệch ngầm, mất răng, sai khớp cắn, viêm quanh cuống răng. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Đau nhức răng dữ dội về đêm, buốt răng khi ăn đồ nóng lạnh, chảy máu chân răng khi chải răng, sưng má khó há miệng. 3. Hướng dẫn chuẩn bị trước khi khám: Vệ sinh răng miệng sạch sẽ, thông báo nếu có bệnh tim mạch, huyết áp hoặc đang sử dụng thuốc chống đông máu. 4. Quy trình thăm khám và chăm sóc: Khám lâm sàng răng miệng -> Chụp X-quang Panorama toàn cảnh hoặc CT Cone Beam 3D -> Lên kế hoạch điều trị bảo tồn răng thật. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Hàn trám răng composite thẩm mỹ, điều trị tủy máy vô trùng, nhổ răng khôn bằng máy siêu âm Piezotome không đau, cấy ghép Implant.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Vệ sinh răng miệng sạch sẽ, thông báo nếu có bệnh tim mạch, huyết áp hoặc đang sử dụng thuốc chống đông máu", "primary_symptoms": "Đau nhức răng dữ dội về đêm, buốt răng khi ăn đồ nóng lạnh, chảy máu chân răng khi chải răng, sưng má khó há miệng", "slug": "rang-ham-mat", "treatment_modalities": "Hàn trám răng composite thẩm mỹ, điều trị tủy máy vô trùng, nhổ răng khôn bằng máy siêu âm Piezotome không đau, cấy ghép Implant", "vietnamese_name": "Răng hàm mặt"}'::jsonb,
