-- [13/215] specialty:ho-hap - Chuyên khoa Hô hấp & Phổi
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'ho-hap',
    'Chuyên khoa Hô hấp & Phổi',
    'Chuyên khoa Hô hấp & Phổi - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Hen phế quản suyễn, bệnh phổi tắc nghẽn mạn tính COPD, viêm phế quản, viêm phổi, giãn phế quản, xơ phổi, ngưng thở khi ngủ. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Ho kéo dài trên 3 tuần, ho có đờm đặc hoặc ho ra máu, khó thở thở khò khè thở rít, đau tức ngực khi hít thở sâu. 3. Hướng dẫn chuẩn bị trước khi khám: Ngưng thuốc xịt giãn phế quản 6-8 giờ trước khi đo chức năng hô hấp (hô hấp ký), không hút thuốc lá 2 giờ trước khám. 4. Quy trình thăm khám và chăm sóc: Nghe tim phổi phát hiện ran rít ran ẩm -> Chụp X-quang phổi thẳng hoặc CT lồng ngực HRCT -> Đo chức năng thông khí phổi Spirometry -> Phác đồ điều trị. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Liệu pháp thuốc hít kiểm soát hen/COPD (ICS/LABA), phục hồi chức năng hô hấp, thở oxy dòng cao hoặc máy thở không xâm lấn BiPAP.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Ngưng thuốc xịt giãn phế quản 6-8 giờ trước khi đo chức năng hô hấp (hô hấp ký), không hút thuốc lá 2 giờ trước khám", "primary_symptoms": "Ho kéo dài trên 3 tuần, ho có đờm đặc hoặc ho ra máu, khó thở thở khò khè thở rít, đau tức ngực khi hít thở sâu", "slug": "ho-hap", "treatment_modalities": "Liệu pháp thuốc hít kiểm soát hen/COPD (ICS/LABA), phục hồi chức năng hô hấp, thở oxy dòng cao hoặc máy thở không xâm lấn BiPAP", "vietnamese_name": "Hô hấp"}'::jsonb,
