-- [15/215] specialty:ung-buou - Chuyên khoa Ung bướu & Tầm soát sớm
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'ung-buou',
    'Chuyên khoa Ung bướu & Tầm soát sớm',
    'Chuyên khoa Ung bướu & Tầm soát sớm - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Tầm soát phát hiện sớm ung thư gan, phổi, dạ dày, đại tràng, vú, cổ tử cung, tuyến giáp; theo dõi sau điều trị và chăm sóc giảm nhẹ. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Xuất hiện khối u bất thường ở vú hoặc cổ, vết loét lâu lành, ho ra máu, thay đổi thói quen đại tiện, sụt cân nhanh trên 10% trọng lượng. 3. Hướng dẫn chuẩn bị trước khi khám: Mang theo toàn bộ hồ sơ sinh thiết mô học, đĩa phim CT/MRI/PET-CT cũ, ghi rõ các phác đồ hóa xạ trị đã từng trải qua. 4. Quy trình thăm khám và chăm sóc: Khám tổng quát hạch ngoại vi -> Xét nghiệm dấu ấn ung thư CEA, AFP, CA 19-9, CA 125, PSA, Chẩn đoán hình ảnh chuyên sâu -> Sinh thiết kim lõi. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Hội chẩn đa chuyên khoa MDT xây dựng phác đồ: phẫu thuật triệt căn, hóa trị, xạ trị, điều trị trúng đích và liệu pháp miễn dịch.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Mang theo toàn bộ hồ sơ sinh thiết mô học, đĩa phim CT/MRI/PET-CT cũ, ghi rõ các phác đồ hóa xạ trị đã từng trải qua", "primary_symptoms": "Xuất hiện khối u bất thường ở vú hoặc cổ, vết loét lâu lành, ho ra máu, thay đổi thói quen đại tiện, sụt cân nhanh trên 10% trọng lượng", "slug": "ung-buou", "treatment_modalities": "Hội chẩn đa chuyên khoa MDT xây dựng phác đồ: phẫu thuật triệt căn, hóa trị, xạ trị, điều trị trúng đích và liệu pháp miễn dịch", "vietnamese_name": "Ung bướu"}'::jsonb,
