-- [17/215] specialty:ngoai-khoa - Chuyên khoa Ngoại tổng quát
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'ngoai-khoa',
    'Chuyên khoa Ngoại tổng quát',
    'Chuyên khoa Ngoại tổng quát - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Viêm ruột thừa cấp, thoát vị bẹn, thoát vị thành bụng, tắc ruột, sỏi túi mật biến chứng viêm, áp xe phần mềm, trĩ, nứt kẽ hậu môn. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Đau bụng cấp tính dữ dội hố chậu phải, nôn ói liên tục, bí trung đại tiện, xuất hiện khối phồng vùng bẹn khi ho, sưng đau rỉ mủ phần mềm. 3. Hướng dẫn chuẩn bị trước khi khám: Tuyệt đối nhịn ăn uống nếu nghi ngờ ruột thừa cấp, không tự uống thuốc giảm đau vì sẽ làm lu mờ dấu hiệu lâm sàng cấp cứu. 4. Quy trình thăm khám và chăm sóc: Khám phản ứng thành bụng và cảm ứng phúc mạc -> Siêu âm bụng cấp cứu, X-quang bụng đứng không chuẩn bị, chụp CT ổ bụng -> Phẫu thuật khẩn. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Phẫu thuật nội soi cắt ruột thừa, phẫu thuật nội soi đặt lưới nhân tạo thoát vị bẹn, mổ rạch dẫn lưu áp xe, cắt trĩ Longo ít đau.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Tuyệt đối nhịn ăn uống nếu nghi ngờ ruột thừa cấp, không tự uống thuốc giảm đau vì sẽ làm lu mờ dấu hiệu lâm sàng cấp cứu", "primary_symptoms": "Đau bụng cấp tính dữ dội hố chậu phải, nôn ói liên tục, bí trung đại tiện, xuất hiện khối phồng vùng bẹn khi ho, sưng đau rỉ mủ phần mềm", "slug": "ngoai-khoa", "treatment_modalities": "Phẫu thuật nội soi cắt ruột thừa, phẫu thuật nội soi đặt lưới nhân tạo thoát vị bẹn, mổ rạch dẫn lưu áp xe, cắt trĩ Longo ít đau", "vietnamese_name": "Ngoại khoa"}'::jsonb,
