-- [19/215] specialty:chan-thuong-chinh-hinh - Chuyên khoa Chấn thương Chỉnh hình
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'chan-thuong-chinh-hinh',
    'Chuyên khoa Chấn thương Chỉnh hình',
    'Chuyên khoa Chấn thương Chỉnh hình - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Gãy xương các chi kín và hở, trật khớp vai háng khuỷu, đứt dây chằng chéo trước/sau khớp gối, rách sụn chêm, gãy cổ xương đùi người già. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Đau chói tại chỗ sau chấn thương, mất khả năng cử động chi, chi biến dạng cong vẹo gập góc bất thường, khớp gối lỏng lẻo trượt. 3. Hướng dẫn chuẩn bị trước khi khám: Cố định tạm chi bằng nẹp trước khi vận chuyển, chườm đá lạnh giảm sưng nề, nhịn ăn uống nếu cần phẫu thuật kết hợp xương cấp cứu. 4. Quy trình thăm khám và chăm sóc: Khám mạch máu thần kinh hạ lưu -> Chụp X-quang xương khớp 2 bình diện, chụp MRI khớp gối đánh giá dây chằng -> Bó bột hoặc phẫu thuật. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Bó bột thủy tinh chịu lực sớm, phẫu thuật nội soi tái tạo dây chằng chéo trước, phẫu thuật kết hợp xương nẹp vít khóa, thay khớp háng nhân tạo.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Cố định tạm chi bằng nẹp trước khi vận chuyển, chườm đá lạnh giảm sưng nề, nhịn ăn uống nếu cần phẫu thuật kết hợp xương cấp cứu", "primary_symptoms": "Đau chói tại chỗ sau chấn thương, mất khả năng cử động chi, chi biến dạng cong vẹo gập góc bất thường, khớp gối lỏng lẻo trượt", "slug": "chan-thuong-chinh-hinh", "treatment_modalities": "Bó bột thủy tinh chịu lực sớm, phẫu thuật nội soi tái tạo dây chằng chéo trước, phẫu thuật kết hợp xương nẹp vít khóa, thay khớp háng nhân tạo", "vietnamese_name": "Chấn thương chỉnh hình"}'::jsonb,
