-- [21/215] specialty:thinh-hoc - Chuyên khoa Thính học & Thăm dò tiền đình
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'thinh-hoc',
    'Chuyên khoa Thính học & Thăm dò tiền đình',
    'Chuyên khoa Thính học & Thăm dò tiền đình - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Giảm thính lực tiếp nhận và dẫn truyền, điếc đột ngột cấp tính, ù tai mạn tính, điếc bẩm sinh trẻ em, rối loạn thăng bằng tiền đình. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Nghe kém, không nghe rõ người khác nói trong môi trường ồn, tiếng ve kêu vo ve liên tục trong tai, cảm giác chòng chành khi nghiêng đầu. 3. Hướng dẫn chuẩn bị trước khi khám: Vệ sinh sạch nút ráy tai trước đo, tránh tiếp xúc với tiếng ồn lớn trên 80dB trong 16 giờ trước khi thực hiện đo thính lực đồ. 4. Quy trình thăm khám và chăm sóc: Khám soi tai màng nhĩ -> Đo thính lực đơn âm trong buồng cách âm chuẩn quốc tế, đo nhĩ lượng phản xạ cơ bàn đạp, đo điện thính giác ABR. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Điều trị cấp cứu điếc đột ngột bằng thuốc giãn mạch và corticoid liều cao trong 72h vàng, hiệu chỉnh máy trợ thính kỹ thuật số, cấy ốc tai.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Vệ sinh sạch nút ráy tai trước đo, tránh tiếp xúc với tiếng ồn lớn trên 80dB trong 16 giờ trước khi thực hiện đo thính lực đồ", "primary_symptoms": "Nghe kém, không nghe rõ người khác nói trong môi trường ồn, tiếng ve kêu vo ve liên tục trong tai, cảm giác chòng chành khi nghiêng đầu", "slug": "thinh-hoc", "treatment_modalities": "Điều trị cấp cứu điếc đột ngột bằng thuốc giãn mạch và corticoid liều cao trong 72h vàng, hiệu chỉnh máy trợ thính kỹ thuật số, cấy ốc tai", "vietnamese_name": "Thính học"}'::jsonb,
