-- [23/215] specialty:giai-phau-benh - Chuyên khoa Giải phẫu bệnh & Tế bào học
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'giai-phau-benh',
    'Chuyên khoa Giải phẫu bệnh & Tế bào học',
    'Chuyên khoa Giải phẫu bệnh & Tế bào học - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Chẩn đoán mô bệnh học khối u lành tính và ác tính, xét nghiệm tế bào học Pap smear, chọc hút tế bào kim nhỏ FNA, hóa mô miễn dịch. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Phát hiện khối u cục ở tuyến giáp, vú, hạch cổ hoặc tổn thương sùi loét niêm mạc qua khám lâm sàng và siêu âm. 3. Hướng dẫn chuẩn bị trước khi khám: Mang đầy đủ khối sáp mô bệnh phẩm, tiêu bản lam kính và giấy kết quả sinh thiết trước đây nếu đến xin hội chẩn lại. 4. Quy trình thăm khám và chăm sóc: Nhận bệnh phẩm phẫu thuật/sinh thiết -> Cắt lọc đúc khối nến -> Cắt lát mỏng 3-4 micromet nhuộm HE -> Bác sĩ đọc dưới kính hiển vi quang học. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Cung cấp kết quả giải phẫu bệnh tiêu chuẩn vàng, nhuộm hóa mô miễn dịch xác định thụ thể HER2, ER, PR, PD-L1 định hướng thuốc trúng đích.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Mang đầy đủ khối sáp mô bệnh phẩm, tiêu bản lam kính và giấy kết quả sinh thiết trước đây nếu đến xin hội chẩn lại", "primary_symptoms": "Phát hiện khối u cục ở tuyến giáp, vú, hạch cổ hoặc tổn thương sùi loét niêm mạc qua khám lâm sàng và siêu âm", "slug": "giai-phau-benh", "treatment_modalities": "Cung cấp kết quả giải phẫu bệnh tiêu chuẩn vàng, nhuộm hóa mô miễn dịch xác định thụ thể HER2, ER, PR, PD-L1 định hướng thuốc trúng đích", "vietnamese_name": "Giải phẫu bệnh"}'::jsonb,
