-- [25/215] specialty:noi-mach-mau - Chuyên khoa Nội Mạch máu & Tĩnh mạch
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'noi-mach-mau',
    'Chuyên khoa Nội Mạch máu & Tĩnh mạch',
    'Chuyên khoa Nội Mạch máu & Tĩnh mạch - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Suy giãn tĩnh mạch chi dưới mạn tính, huyết khối tĩnh mạch sâu DVT, xơ vữa động mạch ngoại biên PAD, viêm tắc động mạch chi, phình động mạch chủ. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Nặng chân mỏi chân, sưng phù mắt cá chân về chiều tối, chuột rút ban đêm, nổi gân xanh ngoằn ngoèo dưới da, đau bắp chân khi đi bộ. 3. Hướng dẫn chuẩn bị trước khi khám: Mặc quần rộng dễ kéo lên đùi để bác sĩ siêu âm mạch máu chân, không bôi dầu nóng hay xoa bóp mạnh vào vùng tĩnh mạch nổi. 4. Quy trình thăm khám và chăm sóc: Khám lâm sàng bắt mạch mu chân -> Đo chỉ số huyết áp cổ chân - cánh tay ABI -> Siêu âm Doppler màu mạch máu hai chi dưới. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Điều trị vớ áp lực y khoa, thuốc trợ tĩnh mạch, tiêm xơ tạo bọt tĩnh mạch, can thiệp laser nội mạch EVLA hoặc sóng cao tần RFA triệt tĩnh mạch suy.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Mặc quần rộng dễ kéo lên đùi để bác sĩ siêu âm mạch máu chân, không bôi dầu nóng hay xoa bóp mạnh vào vùng tĩnh mạch nổi", "primary_symptoms": "Nặng chân mỏi chân, sưng phù mắt cá chân về chiều tối, chuột rút ban đêm, nổi gân xanh ngoằn ngoèo dưới da, đau bắp chân khi đi bộ", "slug": "noi-mach-mau", "treatment_modalities": "Điều trị vớ áp lực y khoa, thuốc trợ tĩnh mạch, tiêm xơ tạo bọt tĩnh mạch, can thiệp laser nội mạch EVLA hoặc sóng cao tần RFA triệt tĩnh mạch suy", "vietnamese_name": "Nội mạch máu"}'::jsonb,
