-- [27/215] specialty:y-hoc-co-truyen - Chuyên khoa Y học cổ truyền & Dưỡng sinh
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'y-hoc-co-truyen',
    'Chuyên khoa Y học cổ truyền & Dưỡng sinh',
    'Chuyên khoa Y học cổ truyền & Dưỡng sinh - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Đau lưng mạn tính, đau thần kinh tọa, liệt mặt ngoại biên dây VII do lạnh, mất ngủ mạn tính, suy nhược cơ thể, thoái hóa khớp. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Đau nhức mỏi cơ xương khớp âm ỉ kéo dài, khó ngủ ngủ trằn trọc, sợ lạnh sợ gió, ăn uống khó tiêu, sắc mặt xanh xao mệt mỏi. 3. Hướng dẫn chuẩn bị trước khi khám: Không ăn quá no hoặc để bụng quá đói trước khi châm cứu, mặc trang phục rộng rãi, không uống trà đặc hoặc cà phê trước khi bắt mạch. 4. Quy trình thăm khám và chăm sóc: Tứ chẩn Vọng Văn Vấn Thiết (nhìn, nghe, hỏi, bắt mạch và xem rêu lưỡi) kết hợp cận lâm sàng hiện đại -> Đưa ra pháp trị đông tây y kết hợp. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Điện châm, thủy châm, cấy chỉ catgut vào huyệt vị giảm đau bền vững, xoa bóp bấm huyệt trị liệu, xông thuốc thảo dược, bài thuốc thang chuẩn GACP.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Không ăn quá no hoặc để bụng quá đói trước khi châm cứu, mặc trang phục rộng rãi, không uống trà đặc hoặc cà phê trước khi bắt mạch", "primary_symptoms": "Đau nhức mỏi cơ xương khớp âm ỉ kéo dài, khó ngủ ngủ trằn trọc, sợ lạnh sợ gió, ăn uống khó tiêu, sắc mặt xanh xao mệt mỏi", "slug": "y-hoc-co-truyen", "treatment_modalities": "Điện châm, thủy châm, cấy chỉ catgut vào huyệt vị giảm đau bền vững, xoa bóp bấm huyệt trị liệu, xông thuốc thảo dược, bài thuốc thang chuẩn GACP", "vietnamese_name": "Y học cổ truyền"}'::jsonb,
