-- [29/215] specialty:da-lieu-tham-my - Chuyên khoa Da liễu Thẩm mỹ & Laser
INSERT INTO healthcare.ai_documents (
    source_type, source_id, title, content, metadata,
    embedding, embedding_model, embedding_dimension, embedding_provenance,
    content_hash, sync_revision, active, published, published_at, deleted_at
) VALUES (
    'specialty',
    'da-lieu-tham-my',
    'Chuyên khoa Da liễu Thẩm mỹ & Laser',
    'Chuyên khoa Da liễu Thẩm mỹ & Laser - Bệnh viện Đa khoa An Tâm tiếp nhận thăm khám, chẩn đoán và điều trị chuyên sâu. 1. Bệnh lý chuyên sâu tiếp nhận: Điều trị sẹo rỗ sau mụn, trị nám má melasma, tàn nhang đồi mồi, xóa xăm, trẻ hóa da xóa nhăn, triệt lông, cấy meso HA căng bóng da. 2. Triệu chứng lâm sàng cảnh báo cần đi khám ngay: Da sần sùi sẹo lõm sau mụn trứng cá, xuất hiện mảng thâm nám sạm da, nếp nhăn đuôi mắt khóe miệng, da chùng nhão chảy xệ. 3. Hướng dẫn chuẩn bị trước khi khám: Ngừng treatment mạnh Retinol, Tretinoin, AHA trước 3 ngày, không trang điểm khi đến khám, tránh tiếp xúc nắng gắt trước liệu trình. 4. Quy trình thăm khám và chăm sóc: Soi da và phân tích đa tầng bằng máy Visia -> Bác sĩ chuyên khoa da liễu khám và lên phác đồ điều trị công nghệ cao cá thể hóa. 5. Phương pháp và kỹ thuật điều trị tiên tiến: Laser CO2 Fractional vi điểm trị sẹo rỗ, Laser Picosecond trị sắc tố nám tàn nhang, công nghệ nâng cơ HIFU/RF vi kim, tiêm vi điểm meso HA chính hãng.',
    '{"category": "specialty", "category_code": "CLINICAL_SPECIALTY", "preparation_guide": "Ngừng treatment mạnh Retinol, Tretinoin, AHA trước 3 ngày, không trang điểm khi đến khám, tránh tiếp xúc nắng gắt trước liệu trình", "primary_symptoms": "Da sần sùi sẹo lõm sau mụn trứng cá, xuất hiện mảng thâm nám sạm da, nếp nhăn đuôi mắt khóe miệng, da chùng nhão chảy xệ", "slug": "da-lieu-tham-my", "treatment_modalities": "Laser CO2 Fractional vi điểm trị sẹo rỗ, Laser Picosecond trị sắc tố nám tàn nhang, công nghệ nâng cơ HIFU/RF vi kim, tiêm vi điểm meso HA chính hãng", "vietnamese_name": "Da liễu thẩm mỹ"}'::jsonb,
